style.css:
@-moz-document domain("facebook.com") {
* {
        font-family: 'Euclid Circular A', 'Noto Naskh Arabic', 'Noto Nastaliq Urdu', 'Segoe UI', sans-serif !important;
        line-height: 1.5 !important;
    }
}

@-moz-document domain("x.com"), domain("twitter.com") {
* {
        font-family: 'Euclid Circular A', 'Noto Naskh Arabic', 'Noto Nastaliq Urdu', sans-serif !important;
    }
    
    /* Forces the font swap inside the actual tweet post container */
    [data-testid="tweetText"] *, [data-testid="tweetText"] {
        font-family: 'Euclid Circular A', 'Noto Naskh Arabic', 'Noto Nastaliq Urdu', sans-serif !important;
        line-height: 1.6 !important;
    }
}

@-moz-document domain("youtube.com") {
* {
        font-family: 'Euclid Circular A', 'Noto Naskh Arabic', 'Noto Nastaliq Urdu', sans-serif !important;
    }
    
    /* Targets video titles, descriptions, and comments specifically */
    yt-formatted-string, #text, .title, #video-title, #content-text {
        font-family: 'Euclid Circular A', 'Noto Naskh Arabic', 'Noto Nastaliq Urdu', sans-serif !important;
        line-height: 1.6 !important;
    }
}
